#include <bits/stdc++.h>
using namespace std;

namespace IO {
	template<typename T>
	inline int Read(T &n) {
		T k=0, f=1; char c=getchar();
		while (c<'0' || c>'9') { if (c=='-') f=-1; c=getchar(); }
		while (c>='0' && c<='9') { k=(k<<3)+(k<<1)+(c-'0'); c=getchar(); }
		n = k*f; return 0;
	}
	template<typename T>
	inline void Write(T x) {
		if (x < 0) { putchar('-'); x=-x; }
		if (x > 9) Write(x/10);
		putchar(x%10+'0');
	}
	template<typename T, typename ...Y>
	inline int Read(T &x, Y&... y) { return Read(x) | Read(y...); }
}

#define LL long long
#define FOR(i, a, b) for(LL i=(a); i<=(b); i++)
#define ROF(i, a, b) for(LL i=(a); i>=(b); i--)

const LL MOD1 = 998244353, MOD2 = 1000000007;
LL total_sum_result, total_n_value, count1_var, sum_levels[7];
vector<LL> level_vectors[7];

inline void generate_levels(LL level, LL prefix) {
	if (level == 7) return;
	level_vectors[level].push_back((count1_var - prefix + MOD1) % MOD1);
	sum_levels[level] += (count1_var - prefix + MOD1) % MOD1;
	count1_var++;
	FOR(d, 0, 9) generate_levels(level + 1, prefix * 10 + d);
}

inline bool check_range(LL x) {
	const LL limit = 1e6;
	return x * limit + 999999 <= total_n_value && x * limit * 10 > total_n_value;
}

LL count2, power_ten_arr[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

inline void search(LL level, LL number) {
	if (number > total_n_value) return;
	if (check_range(number)) {
		FOR(i, 0, 6) {
			LL current = ((count2 + 1 - (number * power_ten_arr[i])) % MOD1 + MOD1) % MOD1;
			LL pos = lower_bound(level_vectors[i].begin(), level_vectors[i].end(), MOD1 - current) - level_vectors[i].begin();
			total_sum_result += sum_levels[i] + current * level_vectors[i].size() - MOD1 * (level_vectors[i].size() - pos);
			total_sum_result %= MOD2;
		}
		count2 += count1_var;
	} else {
		count2++;
		(total_sum_result += ((count2 - number) % MOD1 + MOD1) % MOD1) %= MOD2;
		FOR(i, 0, 9) search(level + 1, number * 10 + i);
	}
}

int main() {
	IO::Read(total_n_value);
	generate_levels(0, 0);
	for (int i=0; i<=6; ++i) sort(level_vectors[i].begin(), level_vectors[i].end());
	count2 = -1;
	search(0, 0);
	IO::Write(total_sum_result);
}
